1	import { Router, type IRouter } from "express";
2	import { desc, eq, or, and, inArray } from "drizzle-orm";
3	import { db, messagesTable, courtsTable, notificationsTable, facilitiesTable, userProfilesTable, bookingsTable } from "@workspace/db";
4	import { requireAuth } from "../lib/auth";
5	import { getAuth, clerkClient } from "@clerk/express";
6	import { socketEmit } from "../lib/socket";
7	
8	const router: IRouter = Router();
9	
10	// Explicit whitelist: `messages` rows hold both parties' email addresses
11	// (senderEmail / recipientEmail) for legacy emailer flows. Those must never
12	// leave the server in API responses — see CLAUDE.md "Data serialization".
13	function formatMsg(r: typeof messagesTable.$inferSelect) {
14	  return {
15	    id: r.id,
16	    courtId: r.courtId,
17	    senderUserId: r.senderUserId,
18	    senderName: r.senderName,
19	    recipientUserId: r.recipientUserId,
20	    subject: r.subject,
21	    body: r.body,
22	    createdAt: r.createdAt.toISOString(),
23	  };
24	}
25	
26	// GET /messages/inbox  — all threads the authenticated user participated in
27	router.get("/messages/inbox", requireAuth, async (req, res): Promise<void> => {
28	  const { userId } = getAuth(req);
29	
30	  const rows = await db
31	    .select()
32	    .from(messagesTable)
33	    .where(or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!)))
34	    .orderBy(desc(messagesTable.createdAt));
35	
36	  // Group by courtId — each court is one thread
37	  const threadMap = new Map<number, typeof rows>();
38	  for (const row of rows) {
39	    if (!threadMap.has(row.courtId)) threadMap.set(row.courtId, []);
40	    threadMap.get(row.courtId)!.push(row);
41	  }
42	
43	  const courtIds = [...threadMap.keys()];
44	  const courts = courtIds.length
45	    ? await db.select({ id: courtsTable.id, name: courtsTable.name }).from(courtsTable).where(inArray(courtsTable.id, courtIds))
46	    : [];
47	  const courtNameMap = new Map(courts.map(c => [c.id, c.name]));
48	
49	  const threads = [...threadMap.entries()].map(([courtId, msgs]) => ({
50	    courtId,
51	    courtName: courtNameMap.get(courtId) ?? `Kortas #${courtId}`,
52	    lastMessage: formatMsg(msgs[0]),
53	    unread: 0,
54	  }));
55	
56	  res.json(threads);
57	});
58	
59	// GET /messages/owner-inbox  — all threads across the authenticated owner's courts
60	router.get("/messages/owner-inbox", requireAuth, async (req, res): Promise<void> => {
61	  const { userId: ownerUserId } = getAuth(req);
62	
63	  const ownedCourts = await db
64	    .select({ id: courtsTable.id, name: courtsTable.name })
65	    .from(courtsTable)
66	    .innerJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
67	    .where(eq(facilitiesTable.ownerUserId, ownerUserId!));
68	
69	  if (ownedCourts.length === 0) { res.json([]); return; }
70	
71	  const courtIds = ownedCourts.map(c => c.id);
72	  const courtNameMap = new Map(ownedCourts.map(c => [c.id, c.name]));
73	
74	  const rows = await db
75	    .select()
76	    .from(messagesTable)
77	    .where(inArray(messagesTable.courtId, courtIds))
78	    .orderBy(desc(messagesTable.createdAt));
79	
80	  // Group by courtId + the non-owner userId (thread key)
81	  const threadMap = new Map<string, typeof rows>();
82	  for (const row of rows) {
83	    const userSide = row.senderUserId === ownerUserId ? row.recipientUserId : row.senderUserId;
84	    const key = `${row.courtId}__${userSide}`;
85	    if (!threadMap.has(key)) threadMap.set(key, []);
86	    threadMap.get(key)!.push(row);
87	  }
88	
89	  const rawThreads = [...threadMap.entries()].map(([key, msgs]) => {
90	    const [courtIdStr, threadUserId] = key.split("__");
91	    const courtId = Number(courtIdStr);
92	    const first = msgs[0];
93	    const userSide = first.senderUserId === ownerUserId ? first : msgs.find(m => m.senderUserId !== ownerUserId) ?? first;
94	    return {
95	      courtId,
96	      courtName: courtNameMap.get(courtId) ?? `Kortas #${courtId}`,
97	      threadUserId,
98	      threadUserName: userSide.senderUserId !== ownerUserId ? userSide.senderName : (userSide.recipientEmail ?? "Vartotojas"),
99	      lastMessage: formatMsg(first),
100	      unread: 0,
101	    };
102	  });
103	
104	  // Fetch profile image URLs for all thread users
105	  const threadUserIds = [...new Set(rawThreads.map(t => t.threadUserId))];
106	  const profileRows = threadUserIds.length
107	    ? await db.select({ userId: userProfilesTable.userId, imageUrl: userProfilesTable.imageUrl })
108	        .from(userProfilesTable)
109	        .where(inArray(userProfilesTable.userId, threadUserIds))
110	    : [];
111	  const imageMap = new Map(profileRows.map(p => [p.userId, p.imageUrl]));
112	
113	  // Fetch most-recent booking per (courtId, threadUserId) for booking context
114	  const bookingRows = rawThreads.length
115	    ? await db.select({
116	        id: bookingsTable.id,
117	        courtId: bookingsTable.courtId,
118	        bookerUserId: bookingsTable.bookerUserId,
119	        date: bookingsTable.date,
120	        startTime: bookingsTable.startTime,
121	        endTime: bookingsTable.endTime,
122	        status: bookingsTable.status,
123	      })
124	        .from(bookingsTable)
125	        .where(
126	          and(
127	            inArray(bookingsTable.courtId, courtIds),
128	            inArray(bookingsTable.bookerUserId, threadUserIds as [string, ...string[]]),
129	          ),
130	        )
131	        .orderBy(desc(bookingsTable.date))
132	    : [];
133	
134	  // Build a map: `${courtId}__${userId}` → most recent booking
135	  const bookingMap = new Map<string, typeof bookingRows[0]>();
136	  for (const b of bookingRows) {
137	    const key = `${b.courtId}__${b.bookerUserId}`;
138	    if (!bookingMap.has(key)) bookingMap.set(key, b);
139	  }
140	
141	  const threads = rawThreads.map(t => {
142	    const bk = bookingMap.get(`${t.courtId}__${t.threadUserId}`);
143	    return {
144	      ...t,
145	      threadUserImageUrl: imageMap.get(t.threadUserId) ?? null,
146	      latestBooking: bk
147	        ? {
148	            id: bk.id,
149	            date: bk.date,
150	            startTime: bk.startTime,
151	            endTime: bk.endTime,
152	            status: bk.status,
153	          }
154	        : null,
155	    };
156	  });
157	
158	  res.json(threads);
