162	// Optional ?userId=… narrows to a single owner↔customer thread; only the court
163	// owner is allowed to filter this way (otherwise it would expose other users'
164	// messages on the same court).
165	router.get("/courts/:id/messages", requireAuth, async (req, res): Promise<void> => {
166	  const courtId = Number(req.params.id);
167	  const { userId } = getAuth(req);
168	  if (Number.isNaN(courtId)) {
169	    res.status(400).json({ error: "courtId is required" });
170	    return;
171	  }
172	
173	  const threadUserIdRaw = req.query.userId;
174	  const threadUserId = typeof threadUserIdRaw === "string" ? threadUserIdRaw : undefined;
175	
176	  const [court] = await db.select({ ownerUserId: facilitiesTable.ownerUserId })
177	    .from(courtsTable)
178	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
179	    .where(eq(courtsTable.id, courtId));
180	  const isOwner = !!court && court.ownerUserId === userId;
181	
182	  // Owner asking for a specific thread → only messages between owner and that customer.
183	  if (isOwner && threadUserId) {
184	    const rows = await db
185	      .select()
186	      .from(messagesTable)
187	      .where(and(
188	        eq(messagesTable.courtId, courtId),
189	        or(
190	          and(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, threadUserId)),
191	          and(eq(messagesTable.senderUserId, threadUserId), eq(messagesTable.recipientUserId, userId!)),
192	        ),
193	      ))
194	      .orderBy(messagesTable.createdAt);
195	    res.json(rows.map(formatMsg));
196	    return;
197	  }
198	
199	  // Default: only messages where caller is sender or recipient.
200	  const rows = await db
201	    .select()
202	    .from(messagesTable)
203	    .where(and(eq(messagesTable.courtId, courtId), or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!))))
204	    .orderBy(messagesTable.createdAt);
205	
206	  res.json(rows.map(formatMsg));
