576	// POST /coaches/apply-to-facility — coach applies to teach at every court in a facility
577	router.post("/coaches/apply-to-facility", requireCoach, async (req, res): Promise<void> => {
578	  const userId = getCurrentUserId(req)!;
579	  const { facilityId, message } = req.body ?? {};
580	  const fid = Number(facilityId);
581	  if (!Number.isFinite(fid)) { res.status(400).json({ error: "facilityId is required" }); return; }
582	
583	  const [facility] = await db.select().from(facilitiesTable).where(eq(facilitiesTable.id, fid));
584	  if (!facility) { res.status(404).json({ error: "Facility not found" }); return; }
585	
586	  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));
587	  if (!coach) { res.status(400).json({ error: "Create your coach profile first" }); return; }
588	
589	  const facilityCourts = await db.select().from(courtsTable).where(eq(courtsTable.facilityId, fid));
590	  if (facilityCourts.length === 0) { res.status(400).json({ error: "Facility has no courts" }); return; }
591	
592	  const courtIds = facilityCourts.map(c => c.id);
593	
594	  // Skip courts where this coach is already approved
595	  const alreadyLinked = await db.select({ courtId: courtCoachesTable.courtId })
596	    .from(courtCoachesTable)
597	    .where(and(eq(courtCoachesTable.coachId, coach.id), inArray(courtCoachesTable.courtId, courtIds)));
598	  const linkedCourtIds = new Set(alreadyLinked.map(r => r.courtId));
599	
600	  // Skip courts with an existing pending invitation by this coach
601	  const existingPending = await db.select({ courtId: courtCoachInvitationsTable.courtId })
602	    .from(courtCoachInvitationsTable)
603	    .where(and(
604	      eq(courtCoachInvitationsTable.targetUserId, userId),
605	      eq(courtCoachInvitationsTable.initiatedBy, "coach"),
606	      eq(courtCoachInvitationsTable.status, "pending"),
607	      inArray(courtCoachInvitationsTable.courtId, courtIds),
608	    ));
609	  const pendingCourtIds = new Set(existingPending.map(r => r.courtId));
610	
611	  const toInsert = facilityCourts
612	    .filter(c => !linkedCourtIds.has(c.id) && !pendingCourtIds.has(c.id))
613	    .map(c => ({
614	      courtId: c.id,
615	      targetUserId: userId,
616	      targetEmail: coach.email,
617	      targetName: coach.name,
618	      initiatedBy: "coach" as const,
619	      status: "pending" as const,
620	      message: message ?? null,
621	    }));
622	
623	  if (toInsert.length === 0) {
624	    res.status(409).json({ error: "Already applied or active at every court in this facility", created: 0 });
625	    return;
626	  }
627	
628	  const created = await db.insert(courtCoachInvitationsTable).values(toInsert).returning();
629	
630	  if (facility.ownerUserId) {
631	    await sendNotification(facility.ownerUserId, "coach_application",
632	      "Naujas trenerio prašymas",
633	      `${coach.name} prašo dirbti „${facility.name}"`,
634	      `/owner/coaches`,
635	    ).catch(() => {});
636	  }
637	
638	  res.status(201).json({
639	    created: created.length,
640	    skipped: facilityCourts.length - created.length,
641	    invitations: created.map(i => ({ ...i, createdAt: i.createdAt.toISOString() })),
642	  });
643	});
